/** Fields the form collects. Nothing else is accepted. */
export const FIELDS = Object.freeze([
  'locations', 'treatmentRooms', 'injectorFte', 'openHoursPerWeek',
  'annualRevenue', 'revenueInjectables', 'revenueEnergy', 'revenueRetail', 'revenueMemberships',
  'newPatientsPerMonth', 'returningPatientShare',
  'averageTicket', 'activeMembers', 'monthlyMarketingSpend',
  'state', 'metroTier',
]);

/** The first four are required; everything else is optional. */
export const REQUIRED_FIELDS = Object.freeze(['locations', 'treatmentRooms', 'injectorFte', 'openHoursPerWeek']);

export const METRO_TIERS = Object.freeze(['major_metro', 'secondary_metro', 'suburban', 'rural']);

/** Which two metrics show before the email gate. */
export const UNGATED_METRICS = Object.freeze(['revenue_per_chair_hour', 'revenue_per_treatment_room']);

const WEEKS_PER_YEAR = 52;

const num = (v) => (typeof v === 'number' && isFinite(v) ? v : null);
const positive = (v) => (num(v) !== null && v > 0 ? v : null);
const round = (v, dp = 2) => (v === null ? null : Math.round(v * (10 ** dp)) / (10 ** dp));

/**
 * Compute every metric the inputs support.
 * A metric whose inputs are missing comes back with `value: null` and a
 * `missing` list naming what it would need, so the form can ask for it.
 */
export function computeMetrics(input = {}) {
  const locations = positive(input.locations);
  const rooms = positive(input.treatmentRooms);
  const injectors = positive(input.injectorFte);
  const hours = positive(input.openHoursPerWeek);
  const revenue = positive(input.annualRevenue);
  const newPatients = positive(input.newPatientsPerMonth);
  const returning = num(input.returningPatientShare);
  const members = num(input.activeMembers);
  const marketing = num(input.monthlyMarketingSpend);

  const injectables = num(input.revenueInjectables);
  const energy = num(input.revenueEnergy);
  const retail = num(input.revenueRetail);
  const memberships = num(input.revenueMemberships);
  const serviceRevenue = [injectables, energy, memberships].some((v) => v !== null)
    ? (injectables || 0) + (energy || 0) + (memberships || 0)
    : null;

  const metrics = {};
  const add = (id, value, { unit, missing = [], detail = null }) => {
    metrics[id] = { id, value: value === null ? null : round(value, 4), unit, missing, detail };
  };

  // The hero metric. Chair-hours are the capacity a practice actually sells:
  // an injector can only be in one chair at a time, and an hour not sold is
  // gone. Revenue per chair-hour is the closest thing this industry has to a
  // yield figure.
  add('revenue_per_chair_hour',
    revenue && injectors && hours ? revenue / (injectors * hours * WEEKS_PER_YEAR) : null,
    {
      unit: 'USD per injector chair-hour',
      missing: [
        !revenue && 'annual revenue', !injectors && 'injector FTEs', !hours && 'open hours per week',
      ].filter(Boolean),
      detail: revenue && injectors && hours
        ? { chairHoursPerYear: round(injectors * hours * WEEKS_PER_YEAR, 1) } : null,
    });

  add('revenue_per_treatment_room', revenue && rooms ? revenue / rooms : null, {
    unit: 'USD per room per year',
    missing: [!revenue && 'annual revenue', !rooms && 'treatment rooms'].filter(Boolean),
  });

  // Retail against SERVICE revenue, not against total. Dividing by total would
  // shrink the ratio as retail grew, which inverts the thing being measured.
  add('retail_attach_rate', retail !== null && serviceRevenue ? retail / serviceRevenue : null, {
    unit: 'retail dollars per service dollar',
    missing: [
      retail === null && 'skincare retail revenue',
      !serviceRevenue && 'at least one of injectables, energy device, or membership revenue',
    ].filter(Boolean),
    detail: serviceRevenue ? { serviceRevenue, retailRevenue: retail } : null,
  });

  // Active patients are estimated, not measured. If new patients are (1 - r) of
  // the annual patient base, the base is annual new patients divided by
  // (1 - r). The assumption is stated wherever the number is shown.
  const annualNew = newPatients ? newPatients * 12 : null;
  const activePatients = annualNew !== null && returning !== null && returning >= 0 && returning < 1
    ? annualNew / (1 - returning)
    : null;

  add('membership_penetration', members !== null && activePatients ? members / activePatients : null, {
    unit: 'members per active patient',
    missing: [
      members === null && 'active membership count',
      !annualNew && 'new patients per month',
      (returning === null || returning >= 1) && 'returning patient share',
    ].filter(Boolean),
    detail: activePatients
      ? {
        estimatedActivePatients: Math.round(activePatients),
        assumption: 'Active patients are estimated as annual new patients divided by one minus the '
          + 'returning patient share. It is an estimate from the figures supplied, not a count.',
      }
      : null,
  });

  add('injectable_mix', injectables !== null && revenue ? injectables / revenue : null, {
    unit: 'share of total revenue',
    missing: [injectables === null && 'injectable revenue', !revenue && 'annual revenue'].filter(Boolean),
  });

  add('new_patient_acquisition_cost', marketing !== null && newPatients ? marketing / newPatients : null, {
    unit: 'USD per new patient',
    missing: [
      marketing === null && 'monthly marketing spend',
      !newPatients && 'new patients per month',
    ].filter(Boolean),
  });

  add('revenue_per_new_patient', revenue && annualNew ? revenue / annualNew : null, {
    unit: 'USD per new patient per year',
    missing: [!revenue && 'annual revenue', !newPatients && 'new patients per month'].filter(Boolean),
  });

  // Three figures the practice supplies directly. They are echoed back as
  // metrics because they are the ONLY places cohort v1 can offer a real,
  // sourced comparison: AmSpa publishes an average for each. Without them the
  // report would compute seven metrics and compare none of them.
  add('annual_revenue', revenue, {
    unit: 'USD per year',
    missing: [!revenue && 'annual revenue'].filter(Boolean),
  });
  add('average_ticket', positive(input.averageTicket), {
    unit: 'USD per visit',
    missing: [!positive(input.averageTicket) && 'average ticket'].filter(Boolean),
  });
  add('returning_patient_share', returning !== null && returning >= 0 && returning <= 1 ? returning : null, {
    unit: 'share of patients',
    missing: [returning === null && 'returning patient share'].filter(Boolean),
  });

  // Revenue split, reported when it is supplied and when it reconciles.
  if (revenue && [injectables, energy, retail, memberships].every((v) => v !== null)) {
    const declared = injectables + energy + retail + memberships;
    metrics.revenue_split_check = {
      id: 'revenue_split_check',
      value: round(declared / revenue, 4),
      unit: 'declared split over stated revenue',
      missing: [],
      detail: {
        reconciles: Math.abs(declared - revenue) <= revenue * 0.02,
        declared,
        stated: revenue,
        note: 'The four categories should account for total revenue. A gap usually means a line of '
          + 'business was left out rather than an error in the figures.',
      },
    };
  }

  return metrics;
}

