// ---------------------------------------------------------------------------
// Comparison against the cohort
// ---------------------------------------------------------------------------

/** Below this, a cut cannot support a percentile and the band is widened. */
export const MIN_N_FOR_PERCENTILE = 30;

/** Percentile of `value` within a sorted distribution of knots. */
export function percentileOf(value, distribution) {
  const knots = distribution.knots;
  if (!knots || knots.length < 2) return null;
  if (value <= knots[0].value) return knots[0].p;
  const last = knots[knots.length - 1];
  if (value >= last.value) return last.p;
  for (let i = 1; i < knots.length; i += 1) {
    const a = knots[i - 1];
    const b = knots[i];
    if (value <= b.value) {
      return a.p + ((value - a.value) / (b.value - a.value)) * (b.p - a.p);
    }
  }
  return null;
}

/**
 * Compare one computed metric to the cohort.
 *
 * Returns one of four shapes, and the caller must render all four:
 *   percentile        a real distribution with enough n behind it
 *   wide_band         a distribution with n under 30, reported as a band plus n
 *   ratio_to_average  only a published mean exists, so no percentile is possible
 *   none              the cohort has no basis for this metric at all
 */
export function compareToCohort(metricId, value, cohort, cutId = 'all') {
  if (value === null || value === undefined) {
    return { type: 'none', reason: 'No value was computed for this metric.' };
  }

  if (cohort.unavailable && cohort.unavailable[metricId]) {
    return { type: 'none', reason: cohort.unavailable[metricId], cohortVersion: cohort.cohortVersion };
  }

  const cut = cohort.cuts && cohort.cuts[cutId];
  if (!cut) return { type: 'none', reason: `The cohort has no cut named "${cutId}".` };

  const entry = cut.metrics && cut.metrics[metricId];
  if (!entry) {
    return {
      type: 'none',
      reason: 'The seed cohort carries no figure for this metric, so there is nothing to compare against.',
      cohortVersion: cohort.cohortVersion,
    };
  }

  const base = {
    cohortVersion: cohort.cohortVersion,
    cutId,
    cutLabel: cut.label,
    n: cut.n,
    sourceId: entry.sourceId,
    note: entry.note || null,
  };

  if (entry.distribution && Array.isArray(entry.distribution.knots)) {
    const p = percentileOf(value, entry.distribution);
    const n = entry.distribution.n ?? cut.n;

    // Thin cuts get a band and their n, never a two-decimal percentile.
    if (n === null || n === undefined || n < MIN_N_FOR_PERCENTILE) {
      return {
        ...base,
        type: 'wide_band',
        n,
        band: bandFor(p),
        percentileSuppressed: true,
        reason: `Only ${n === null || n === undefined ? 'an unknown number of' : n} practices sit in this cut, `
          + `below the ${MIN_N_FOR_PERCENTILE} needed for a percentile. A band is shown instead.`,
      };
    }
    return { ...base, type: 'percentile', n, percentile: round(p, 0), band: bandFor(p) };
  }

  // A mean with no spread behind it. This is every metric in cohort v1.
  return {
    ...base,
    type: 'ratio_to_average',
    average: entry.central,
    centralType: entry.centralType,
    ratio: round(value / entry.central, 3),
    direction: value >= entry.central ? 'above' : 'below',
    reason: 'The published source reports an average, not a distribution, so a percentile cannot be '
      + 'computed. This is a comparison to that average.',
  };
}

/** Coarse bands, used wherever a percentile would be false precision. */
export function bandFor(p) {
  if (p === null || p === undefined) return null;
  if (p < 33) return 'lower third';
  if (p < 67) return 'middle third';
  return 'upper third';
}

