/** Compute, compare, and attach the plain-language read. */
export function buildReport(input, cohort, { cutId = 'all' } = {}) {
  const metrics = computeMetrics(input);
  const results = [];

  for (const [id, metric] of Object.entries(metrics)) {
    results.push({
      ...metric,
      comparison: compareToCohort(id, metric.value, cohort, cutId),
      read: READS[id] || null,
      ungated: UNGATED_METRICS.includes(id),
    });
  }

  return {
    cohortVersion: cohort.cohortVersion,
    cohortLabel: cohort.label,
    cohortDerivedAt: cohort.derivedAt,
    cutId,
    metrics: results,
    notComputable: NOT_COMPUTABLE,
    context: {
      nationalFillerToToxinRatio: cohort.cuts?.all?.metrics?.filler_to_toxin_ratio?.central ?? null,
    },
  };
}
